__forceinline
int
RtlConstantTimeEqualMemory(
      const void* v1,
      const void* v2,
    unsigned long len
    )
{
    char x = 0;
    unsigned long i = 0;

    
    volatile const char* p1 = (volatile const char*) v1;
    volatile const char* p2 = (volatile const char*) v2;

    for (; i < len; i += 1) {














        x |= p1[i] ^ p2[i];



    }

    return x == 0;
}











__forceinline
PVOID
RtlSecureZeroMemory(
      PVOID ptr,
      SIZE_T cnt
    )
{
    volatile char *vptr = (volatile char *)ptr;



    __stosb((PBYTE )((DWORD64)vptr), 0, cnt);





















    return ptr;
}







